// Converts components generated by the shadcn CLI to this app's design tokens (spec §4.2):
//
// - Spacing: shadcn writes classes for Tailwind's default 4px unit; this app's unit is 8px
//   (`--spacing` in app/globals.css), so every spacing number is halved: h-8 (32px) becomes h-4.
// - Type scale: t-shirt sizes become the spec's pixel steps (text-sm becomes text-14).
// - Focus: shadcn's 3px translucent ring becomes the 2px --brand ring of §4.7.
// - Imports: `cn` comes from "@/lib/utils", which knows the custom theme keys.
//
// A converted file is marked on its first line and skipped next time, so the script is safe to rerun.
// Usage: node scripts/shadcn-8px.mjs [files...]   (default: every file in components/ui)
// Most of the time run it through `npm run ui:add -- <component>`.

import fs from "node:fs"
import path from "node:path"

const MARKER = "// tokens: 8px spacing, spec type scale (scripts/shadcn-8px.mjs)"

const SPACING_UTILITIES = [
  "p", "px", "py", "ps", "pe", "pt", "pr", "pb", "pl",
  "m", "mx", "my", "ms", "me", "mt", "mr", "mb", "ml",
  "gap", "gap-x", "gap-y", "space-x", "space-y",
  "w", "h", "size", "min-w", "min-h", "max-w", "max-h",
  "inset", "inset-x", "inset-y", "start", "end", "top", "right", "bottom", "left",
  "translate-x", "translate-y", "scroll-m", "scroll-mx", "scroll-my", "scroll-mt", "scroll-mb",
  "scroll-p", "scroll-px", "scroll-py", "indent", "basis",
  // tw-animate-css offsets are spacing multiples too.
  "slide-in-from-top", "slide-in-from-bottom", "slide-in-from-left", "slide-in-from-right",
  "slide-out-to-top", "slide-out-to-bottom", "slide-out-to-left", "slide-out-to-right",
]

// A class starts after whitespace, a quote, a backtick or a variant separator, and may end in the
// important modifier (h-8!).
const before = String.raw`(?<=^|[\s"'\`:!(])`
const after = String.raw`(?=$|[\s"'\`)\]!])`
const spacingPattern = new RegExp(
  `${before}(-?)(${SPACING_UTILITIES.join("|")})-(\\d+(?:\\.\\d+)?)${after}`,
  "g",
)

const FONT_SIZES = {
  "text-xs": "text-12",
  "text-[0.8rem]": "text-13",
  "text-sm": "text-14",
  "text-base": "text-16",
  "text-lg": "text-16",
  "text-xl": "text-20",
  "text-2xl": "text-24",
  "text-3xl": "text-30",
}
const fontPattern = new RegExp(
  `${before}(${Object.keys(FONT_SIZES).map((k) => k.replace(/[[\].]/g, "\\$&")).join("|")})${after}`,
  "g",
)

function convert(source) {
  return source
    .replace(spacingPattern, (_, sign, utility, value) => `${sign}${utility}-${Number(value) / 2}`)
    .replace(fontPattern, (match) => FONT_SIZES[match])
    // §4.7: the focus ring is a solid 2px --brand, not shadcn's 3px half-transparent one.
    .replace(/focus-visible:ring-3/g, "focus-visible:ring-2")
    .replace(/ring-ring\/50/g, "ring-ring")
    .replace(/from "cn"/g, 'from "@/lib/utils"')
}

const root = path.resolve(import.meta.dirname, "..")
const files = process.argv.length > 2
  ? process.argv.slice(2).map((f) => path.resolve(f))
  : fs.readdirSync(path.join(root, "components/ui"))
      .filter((f) => f.endsWith(".tsx"))
      .map((f) => path.join(root, "components/ui", f))

for (const file of files) {
  const source = fs.readFileSync(file, "utf8")
  if (source.includes(MARKER)) continue

  // Keep a "use client" directive as the first statement.
  const directive = source.match(/^(["']use client["'];?\r?\n)/)?.[1] ?? ""
  const body = source.slice(directive.length)
  fs.writeFileSync(file, `${directive}${MARKER}\n${convert(body)}`)
  console.log(`converted ${path.relative(root, file)}`)
}
